-- Self-Auth, Migration A (backward compatible). The Self-Auth tables, and every helper that reads auth.* now
-- also reads self_auth.*, so redeploying the previous app release (Supabase Auth) keeps working. The foreign
-- keys to auth.users are dropped here; Migration B (0103) re-adds them pointing at self_auth."user" once the
-- rollback window has closed.

-- ── Self-Auth schema (packages/self-auth/sql/0001_self_auth.sql, verbatim) ───────────────────────────────
-- Self-Auth schema 0001: Better Auth tables (generated by getMigrations(...).compileMigrations()), schema-qualified.
create schema if not exists self_auth;

create table self_auth."user" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "companyId" text not null, "realEmail" text not null, "disabled" boolean);

create table self_auth."session" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" uuid not null references self_auth."user" ("id") on delete cascade, "aal" text);

create table self_auth."account" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "accountId" text not null, "providerId" text not null, "userId" uuid not null references self_auth."user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table self_auth."verification" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create index "session_userId_idx" on self_auth."session" ("userId");

create index "account_userId_idx" on self_auth."account" ("userId");

create index "verification_identifier_idx" on self_auth."verification" ("identifier");

create table self_auth.sign_in_failure (login_key text primary key, count int not null, last_at timestamptz not null);

create table self_auth.totp_factor (user_id uuid primary key references self_auth."user"(id) on delete cascade, secret_enc text not null, confirmed boolean not null default false, last_step bigint, created_at timestamptz not null default now());

-- The app reaches these tables only over its own connection (and the postgres-owned definers below); the API
-- roles get nothing, so no token, secret or session row is ever readable through PostgREST.
revoke all on schema self_auth from public, anon, authenticated, service_role;
revoke all on all tables in schema self_auth from public, anon, authenticated, service_role;

-- ── Helpers that read both sources ───────────────────────────────────────────────────────────────────────

-- 0089's mfa_satisfied: a verified Supabase factor or a confirmed Self-Auth factor makes aal2 necessary.
create or replace function app_private.mfa_satisfied() returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare
  v_user uuid := app.current_user_id();
begin
  return (coalesce(app.current_aal(), 'aal1') = 'aal2'
          or not (exists (select 1 from auth.mfa_factors f where f.user_id = v_user and f.status = 'verified')
                  or exists (select 1 from self_auth.totp_factor t where t.user_id = v_user and t.confirmed)))
    and not exists (select 1 from public.company_members m
                    where m.company_id = app.current_company_id() and m.user_id = v_user and m.mfa_setup_required);
end $$;

-- 0089's mfa_setup_done: the factor, from either source, must be newer than the latest reset.
create or replace function public.mfa_setup_done() returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_user uuid := app.current_user_id();
  v_company uuid := app.current_company_id();
  v_reset timestamptz;
begin
  if v_user is null then
    perform app_private.fail('Sign in first.');
  end if;
  if v_company is null then
    perform app_private.fail('This session is not linked to a company. Sign in again.');
  end if;
  v_reset := coalesce(
    (select max(e.at) from public.admin_events e where e.user_id = v_user and e.kind = 'mfa_reset'),
    '-infinity'::timestamptz);
  -- The factor must be newer than the latest reset: one that survived it (a failed deletion) is the
  -- lost phone's, and must not lift the requirement.
  if coalesce(app.current_aal(), '') <> 'aal2'
     or not (exists (select 1 from auth.mfa_factors f
                     where f.user_id = v_user and f.status = 'verified' and f.created_at > v_reset)
             or exists (select 1 from self_auth.totp_factor t
                        where t.user_id = v_user and t.confirmed and t.created_at > v_reset)) then
    perform app_private.fail('Finish setting up two-factor authentication first.');
  end if;
  update public.company_members set mfa_setup_required = false where company_id = v_company and user_id = v_user;
end $$;

-- 0092's bind_session: a binding survives while its session is alive in auth.sessions or in
-- self_auth.session (not expired).
create or replace function app.bind_session(p_company uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_session uuid := app.current_session_id();
  v_user uuid := app.current_user_id();
  v_bound app.session_companies;
begin
  if v_session is null or v_user is null then
    perform app_private.fail('No sign-in session.');
  end if;
  if not exists (select 1 from public.company_members m
                 where m.company_id = p_company and m.user_id = v_user) then
    perform app_private.fail('You do not have access to this company.');
  end if;
  insert into app.session_companies (session_id, company_id, user_id)
  values (v_session, p_company, v_user)
  on conflict (session_id) do nothing;
  select * into v_bound from app.session_companies where session_id = v_session;
  if v_bound.company_id <> p_company or v_bound.user_id <> v_user then
    perform app_private.fail('You do not have access to this company.');
  end if;
  delete from app.session_companies sc
  where sc.user_id = v_user
    and sc.session_id <> v_session
    and not exists (select 1 from auth.sessions s where s.id = sc.session_id)
    and not exists (select 1 from self_auth.session s where s.id = sc.session_id and s."expiresAt" > now());
end $$;

-- 0090's admin_end_sessions: the sessions bound to the caller's company, in both session tables.
create or replace function public.admin_end_sessions(p_user uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_company uuid;
begin
  perform app_private.require_perm('delegates', 'edit');
  if not public.is_admin() then
    perform app_private.fail('Only an admin can do this.');
  end if;
  v_company := app_private.admin_company('Only an admin can do this.', false);
  delete from auth.sessions s
  where s.user_id = p_user
    and s.id in (select sc.session_id from app.session_companies sc
                 where sc.company_id = v_company and sc.user_id = p_user);
  delete from self_auth.session s
  where s."userId" = p_user
    and s.id in (select sc.session_id from app.session_companies sc
                 where sc.company_id = v_company and sc.user_id = p_user);
end $$;

-- ── Provisioning for Self-Auth users ─────────────────────────────────────────────────────────────────────
-- 0090's handle_new_user, keyed on the Self-Auth user's id and real email. A user that already has a profile
-- (imported from Supabase Auth with the same id) is not provisioned again.
-- Accounts are per company: only the pending logins of new."companyId" are used and removed.
create function app_private.handle_new_self_auth_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_email text := lower(new."realEmail");
  v_name text;
begin
  if exists (select 1 from public.profiles p where p.user_id = new.id) then
    return new;
  end if;
  delete from app_private.pending_logins where email = v_email and created_at < now() - interval '7 days';
  select pl.full_name into v_name from app_private.pending_logins pl
  where pl.email = v_email and pl.company_id::text = new."companyId" order by pl.created_at desc limit 1;
  if not found then
    perform app_private.fail('No pending login for this address.');
  end if;
  insert into public.profiles (user_id, email, full_name) values (new.id, v_email, v_name);
  insert into public.company_members (company_id, user_id, role, active, delegate_id)
  select pl.company_id, new.id, pl.role, true, pl.delegate_id
  from app_private.pending_logins pl
  where pl.email = v_email and pl.company_id::text = new."companyId"
    and (pl.delegate_id is null
         or exists (select 1 from public.delegates d where d.company_id = pl.company_id and d.id = pl.delegate_id))
  on conflict do nothing;
  delete from app_private.pending_logins where email = v_email and company_id::text = new."companyId";
  return new;
end $$;
revoke all on function app_private.handle_new_self_auth_user() from public, anon, authenticated;

create trigger self_auth_user_created after insert on self_auth."user"
  for each row execute function app_private.handle_new_self_auth_user();

-- ── Deleting a user ──────────────────────────────────────────────────────────────────────────────────────
-- The foreign keys below did this on delete: the profile (and through it the memberships) goes, and created_by
-- on the rows the user made is cleared. Triggers keep it so for both sources until Migration B restores the keys.
create function app_private.handle_deleted_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.profiles where user_id = old.id;
  update public.patients set created_by = null where created_by = old.id;
  update public.delegates set created_by = null where created_by = old.id;
  update public.products set created_by = null where created_by = old.id;
  update public.courses set created_by = null where created_by = old.id;
  update public.enrollments set created_by = null where created_by = old.id;
  update public.sessions set created_by = null where created_by = old.id;
  update public.talks set created_by = null where created_by = old.id;
  return old;
end $$;
revoke all on function app_private.handle_deleted_user() from public, anon, authenticated;

create trigger on_auth_user_deleted after delete on auth.users
  for each row execute function app_private.handle_deleted_user();
create trigger self_auth_user_deleted after delete on self_auth."user"
  for each row execute function app_private.handle_deleted_user();

-- ── Foreign keys to auth.users ───────────────────────────────────────────────────────────────────────────
alter table public.profiles drop constraint profiles_user_id_fkey;
alter table public.patients drop constraint patients_created_by_fkey;
alter table public.delegates drop constraint delegates_created_by_fkey;
alter table public.products drop constraint products_created_by_fkey;
alter table public.courses drop constraint courses_created_by_fkey;
alter table public.enrollments drop constraint enrollments_created_by_fkey;
alter table public.sessions drop constraint sessions_created_by_fkey;
alter table public.talks drop constraint talks_created_by_fkey;
